// shoppingCart.test.js
import React from 'react';
import { render, fireEvent, screen } from '@testing-library/react';
import { Provider } from 'react-redux';
import configureStore from 'redux-mock-store';
import ShoppingCart from './ShoppingCart';

const mockStore = configureStore([]);

describe('Shopping Cart Module', () => {
  let store;

  beforeEach(() => {
    store = mockStore({
      cart: {
        items: [],
      },
    });
  });

  test('adds an item to the cart', () => {
    render(
      <Provider store={store}>
        <ShoppingCart />
      </Provider>
    );

    fireEvent.click(screen.getByText('Add to Cart'));
    expect(store.getActions()).toEqual([
      { type: 'ADD_TO_CART', payload: { id: 1, name: 'Item 1', price: 10 } },
    ]);
  });

  test('removes an item from the cart', () => {
    store = mockStore({
      cart: {
        items: [{ id: 1, name: 'Item 1', price: 10 }],
      },
    });

    render(
      <Provider store={store}>
        <ShoppingCart />
      </Provider>
    );

    fireEvent.click(screen.getByText('Remove'));
    expect(store.getActions()).toEqual([
      { type: 'REMOVE_FROM_CART', payload: 1 },
    ]);
  });

  test('changes the quantity of an item in the cart', () => {
    store = mockStore({
      cart: {
        items: [{ id: 1, name: 'Item 1', price: 10, quantity: 1 }],
      },
    });

    render(
      <Provider store={store}>
        <ShoppingCart />
      </Provider>
    );

    fireEvent.change(screen.getByLabelText('Quantity'), { target: { value: 2 } });
    expect(store.getActions()).toEqual([
      { type: 'UPDATE_QUANTITY', payload: { id: 1, quantity: 2 } },
    ]);
  });

  test('handles an empty cart', () => {
    render(
      <Provider store={store}>
        <ShoppingCart />
      </Provider>
    );

    expect(screen.getByText('Your cart is empty')).toBeInTheDocument();
  });
});
