// src/components/ShoppingCart.js
import React, { useState } from 'react';
import { FaPlusCircle, FaMinusCircle, FaTrash } from 'lucide-react';

const ShoppingCart = () => {
  const [items, setItems] = useState([]);

  const addItem = (item) => {
    setItems([...items, item]);
  };

  const removeItem = (index) => {
    setItems(items.filter((_, i) => i !== index));
  };

  const changeQuantity = (index, quantity) => {
    const newItems = [...items];
    newItems[index].quantity = quantity;
    setItems(newItems);
  };

  const emptyCart = () => {
    setItems([]);
  };

  return (
    <div>
      <button onClick={() => addItem({ name: 'Item 1', quantity: 1 })}>Add Item 1</button>
      <button onClick={() => addItem({ name: 'Item 2', quantity: 1 })}>Add Item 2</button>
      <ul>
        {items.map((item, index) => (
          <li key={index}>
            {item.name} - {item.quantity}
            <FaPlusCircle onClick={() => changeQuantity(index, item.quantity + 1)} />
            <FaMinusCircle onClick={() => changeQuantity(index, Math.max(item.quantity - 1, 0))} />
            <FaTrash onClick={() => removeItem(index)} />
          </li>
        ))}
      </ul>
      <button onClick={emptyCart}>Empty Cart</button>
    </div>
  );
};

export default ShoppingCart;
