  });

  it('empties the cart', () => {
    render(<ShoppingCart />);
    fireEvent.click(screen.getByText('Add Item 1'));
    fireEvent.click(screen.getByText('Empty Cart'));
    expect(screen.queryByText('Item 1 - 1')).not.toBeInTheDocument();
