  });

  it('should handle empty cart case', () => {
    expect(cart.isEmpty()).toBe(true);
    cart.addItem('Grapes', 1);
    expect(cart.isEmpty()).toBe(false);
    cart.removeItem('Grapes');
    expect(cart.isEmpty()).toBe(true);
  });
