// AutoCompleteInput.tsx
import { h } from 'preact';
import { useState, useRef, useEffect } from 'preact/hooks';
import anime from 'animejs';

interface AutoCompleteInputProps {
  options: string[];
  onSelect: (value: string) => void;
}

const AutoCompleteInput: React.FC<AutoCompleteInputProps> = ({ options, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.focus();
    }
  }, []);

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(event.target.value);
    setShowSuggestions(true);
    setActiveIndex(-1);
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'ArrowUp') {
      setActiveIndex((prev) => Math.max(prev - 1, -1));
    } else if (event.key === 'ArrowDown') {
      setActiveIndex((prev) => Math.min(prev + 1, options.length - 1));
    } else if (event.key === 'Enter' && activeIndex !== -1) {
      onSelect(options[activeIndex]);
      setShowSuggestions(false);
      setInputValue(options[activeIndex]);
    } else if (event.key === 'Escape') {
      setShowSuggestions(false);
      setActiveIndex(-1);
    }
  };

  const handleSuggestionClick = (index: number) => {
    onSelect(options[index]);
    setShowSuggestions(false);
    setInputValue(options[index]);
  };

  useEffect(() => {
    if (showSuggestions && options.length > 0) {
      anime({
        targets: '.suggestion',
        opacity: [0, 1],
        translateY: [-20, 0],
        duration: 300,
        easing: 'easeOutQuad',
      });
    }
  }, [showSuggestions]);

  return (
    <div className="autocomplete-container">
      <input
        ref={inputRef}
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        placeholder="Type to search..."
      />
      {showSuggestions && (
        <ul className="suggestions">
          {options.map((option, index) => (
            <li
              key={index}
              className={`suggestion ${activeIndex === index ? 'active' : ''}`}
              onClick={() => handleSuggestionClick(index)}
            >
              {option}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default AutoCompleteInput;
