<template>
  <div v-if="isOpen" class="lightbox-overlay" @click="closeModal">
    <div class="lightbox-container" @click.stop>
      <button class="close-button" @click="closeModal">X</button>
      <img :src="currentImage" alt="Lightbox Image" class="lightbox-image" />
    </div>
  </div>
</template>

<script>
import { useState } from 'vue';
import { useSpring, animated } from 'react-spring';

export default {
  props: {
    images: {
      type: Array,
      required: true
    },
    isOpen: {
      type: Boolean,
      required: true
    }
  },
  setup(props) {
    const [currentImageIndex, setCurrentImageIndex] = useState(0);

    const closeModal = () => {
      props.$emit('close');
    };

    const nextImage = () => {
      setCurrentImageIndex((prevIndex) => (prevIndex + 1) % props.images.length);
    };

    const prevImage = () => {
      setCurrentImageIndex((prevIndex) => (prevIndex - 1 + props.images.length) % props.images.length);
    };

    const springProps = useSpring({
      opacity: props.isOpen ? 1 : 0,
      transform: props.isOpen ? 'scale(1)' : 'scale(0.9)',
      config: { duration: 300 }
    });

    return {
      currentImage: props.images[currentImageIndex],
      closeModal,
      nextImage,
      prevImage,
      springProps
    };
  }
};
</script>

