{
  "file": "ImageUploadWithCrop.tsx",
  "content": "// ImageUploadWithCrop.tsx
import React, { useState } from 'react';
import { useDropzone } from 'react-dropzone';
import { FcImageFile } from 'lucide-react';
import { motion } from 'framer-motion';
import { Cropper } from 'react-cropper';
import 'cropperjs/dist/cropper.css';

const ImageUploadWithCrop: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [croppedImage, setCroppedImage] = useState<string | null>(null);
  const [isCropping, setIsCropping] = useState(false);

  const onDrop = (acceptedFiles: File[]) => {
    setFile(acceptedFiles[0]);
  };

  const {getRootProps, getInputProps, isDragActive} = useDropzone({onDrop});

  const handleCrop = () => {
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.src = e.target?.result as string;
        img.onload = () => {
          const cropper = new Cropper(img);
          const canvas = cropper.getCroppedCanvas();
          setCroppedImage(canvas.toDataURL());
          setIsCropping(false);
        };
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className='flex flex-col items-center justify-center w-full h-full'>
      {isCropping ? (
        <Cropper
          src={file?.preview as string}
          style={{ height: 400, width: '100%' }}
          guides={true}
          background={true}
          ruleOfThirds={true}
          viewMode={1}
          autoCropArea={1}
          crop='none'
          onCrop={(crop) => console.log(crop)}
        />
      ) : (
        <motion.div
          {...getRootProps()}
          className='border-2 border-dashed border-gray-300 rounded-lg p-4 flex items-center justify-center'
        >
          <input {...getInputProps()} />
          {isDragActive ? (
            <p>Drop the files here ...</p>
          ) : (
            <div className='flex flex-col items-center'>
              <FcImageFile size={48} />
              <p>Upload an image</p>
            </div>
          )}
        </motion.div>
      )}
      {file && !isCropping && (
        <button
          onClick={() => setIsCropping(true)}
          className='mt-4 px-4 py-2 bg-blue-500 text-white rounded'
        >
          Crop Image
        </button>
      )}
      {croppedImage && (
        <div className='mt-4'>
