  border: 1px solid #ccc;
  border-radius: 4px;
}

.is-invalid {
  border-color: red;
}

.invalid-feedback {
  color: red;
  font-size: 0.875rem;
}

.btn-primary {
  padding: 0.5rem 1rem;
  background-color: #007bff;
  border-color: #007bff;
  color: white;
  border-radius: 4px;
  cursor: pointer;
}

