```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Accessible Form</title>
    <style>
        .error {
            color: red;
        }
    </style>
</head>
<body>
    <form id="myForm" novalidate>
        <label for="name">Name:</label>
        <input type="text" id="name" name="name" aria-required="true" aria-invalid="false">
        <span class="error" id="nameError" role="alert" hidden>Name is required.</span>

        <label for="email">Email:</label>
        <input type="email" id="email" name="email" aria-required="true" aria-invalid="false">
        <span class="error" id="emailError" role="alert" hidden>Email is required and must be a valid email address.</span>

        <button type="submit">Submit</button>
    </form>

    <script>
        document.getElementById('myForm').addEventListener('submit', function(event) {
            event.preventDefault();
            validateForm();
        });

        function validateForm() {
            const name = document.getElementById('name');
            const email = document.getElementById('email');

            if (name.value.trim() === '') {
                name.setAttribute('aria-invalid', 'true');
                document.getElementById('nameError').hidden = false;
            } else {
                name.setAttribute('aria-invalid', 'false');
                document.getElementById('nameError').hidden = true;
            }

            if (!email.validity.valid) {
                email.setAttribute('aria-invalid', 'true');
                document.getElementById('emailError').hidden = false;
            } else {
                email.setAttribute('aria-invalid', 'false');
                document.getElementById('emailError').hidden = true;
            }
        }
    </script>
</body>
</html>
