<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Payment Form</title>
    <style>
        .form-group {
            margin-bottom: 15px;
        }
        .form-control {
            width: 100%;
            padding: 8px;
            box-sizing: border-box;
        }
        .error {
            color: red;
        }
    </style>
</head>
<body>
    <form id="paymentForm">
        <div class="form-group">
            <label for="cardNumber">Card Number</label>
            <input type="text" id="cardNumber" class="form-control" placeholder="Enter card number">
            <span class="error" id="cardNumberError"></span>
        </div>
        <div class="form-group">
            <label for="expiryDate">Expiry Date (MM/YY)</label>
            <input type="text" id="expiryDate" class="form-control" placeholder="Enter expiry date">
            <span class="error" id="expiryDateError"></span>
        </div>
        <div class="form-group">
            <label for="cvc">CVC</label>
            <input type="text" id="cvc" class="form-control" placeholder="Enter CVC">
            <span class="error" id="cvcError"></span>
        </div>
        <button type="submit" class="btn btn-primary">Submit</button>
    </form>

    <script>
        document.getElementById('paymentForm').addEventListener('submit', function(event) {
            event.preventDefault();
            validateCardNumber();
            validateExpiryDate();
            validateCVC();
        });

        function validateCardNumber() {
            const cardNumber = document.getElementById('cardNumber').value;
            const cardNumberError = document.getElementById('cardNumberError');
            if (!/^\d{13,16}$/.test(cardNumber)) {
                cardNumberError.textContent = 'Invalid card number';
            } else {
                cardNumberError.textContent = '';
            }
        }

        function validateExpiryDate() {
            const expiryDate = document.getElementById('expiryDate').value;
            const expiryDateError = document.getElementById('expiryDateError');
            if (!/^(0[1-9]|1[0-2])\/\d{2}$/.test(expiryDate)) {
                expiryDateError.textContent = 'Invalid expiry date (MM/YY)';
            } else {
                expiryDateError.textContent = '';
            }
        }

        function validateCVC() {
            const cvc = document.getElementById('cvc').value;
            const cvcError = document.getElementById('cvcError');
            if (!/^\d{3,4}$/.test(cvc)) {
                cvcError.textContent = 'Invalid CVC';
            } else {
                cvcError.textContent = '';
            }
        }

        document.getElementById('cardNumber').addEventListener('input', function() {
            this.value = this.value.replace(/[^\d]/g, '');
        });

        document.getElementById('expiryDate').addEventListener('input', function() {
            this.value = this.value.replace(/[^\d]/g, '').slice(0, 5);
        });

        document.getElementById('cvc').addEventListener('input', function() {
            this.value = this.value.replace(/[^\d]/g, '');
        });
    </script>
</body>
</html>
