import React from 'react';
import { Table } from 'ag-grid-react';
import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css';

interface Expense {
  id: number;
  date: string;
  description: string;
  amount: number;
  category: string;
}

const expenses: Expense[] = Array.from({ length: 500 }, (_, i) => ({
  id: i + 1,
  date: new Date(2023, Math.floor(Math.random() * 12), Math.floor(Math.random() * 28)).toLocaleDateString(),
  description: `Expense ${i + 1}`,
  amount: Math.floor(Math.random() * 1000),
  category: ['Food', 'Travel', 'Utilities', 'Entertainment'][Math.floor(Math.random() * 4)],
}));

const ExpenseTable: React.FC = () => {
  const columnDefs = [
    { headerName: 'ID', field: 'id', sortable: true },
    { headerName: 'Date', field: 'date', sortable: true },
    { headerName: 'Description', field: 'description', sortable: true },
    { headerName: 'Amount', field: 'amount', sortable: true, valueFormatter: params => `$${params.value}` },
    { headerName: 'Category', field: 'category', sortable: true },
  ];

  return (
    <div className="ag-theme-alpine" style={{ height: 400, width: '100%' }}>
      <Table columnDefs={columnDefs} rowData={expenses} />
    </div>
  );
};

export default ExpenseTable;
