        tr:hover {background-color: #ddd;}
    </style>
</head>
<body>

<table id="myTable">
    <thead>
        <tr>
            <th onclick="sortTable(0)">Spalte 1</th>
            <th onclick="sortTable(1)">Spalte 2</th>
            <th onclick="sortTable(2)">Spalte 3</th>
            <!-- Fügen Sie hier weitere Spalten hinzu -->
        </tr>
    </thead>
    <tbody>
        <!-- Fügen Sie hier 500 Zeilen mit Daten ein -->
        <tr>
            <td>Daten 1</td>
            <td>Daten 2</td>
            <td>Daten 3</td>
        </tr>
        <!-- Wiederholen Sie die Zeile 499 mal -->
    </tbody>
</table>

<script>
function sortTable(n) {
    var table, rows, switching, i, x, y, shouldSwitch, dir, switchcount = 0;
    table = document.getElementById("myTable");
    switching = true;
    dir = "asc"; 
    while (switching) {
        switching = false;
        rows = table.rows;
        for (i = 1; i < (rows.length - 1); i++) {
            shouldSwitch = false;
            x = rows[i].getElementsByTagName("TD")[n];
            y = rows[i + 1].getElementsByTagName("TD")[n];
            if (dir == "asc") {
                if (x.innerHTML.toLowerCase() > y.innerHTML.toLowerCase()) {
                    shouldSwitch= true;
                    break;
                }
            } else if (dir == "desc") {
                if (x.innerHTML.toLowerCase() < y.innerHTML.toLowerCase()) {
                    shouldSwitch = true;
                    break;
                }
            }
        }
        if (shouldSwitch) {
            rows[i].parentNode.insertBefore(rows[i + 1], rows[i]);
            switching = true;
            switchcount ++;      
        } else {
            if (switchcount == 0 && dir == "asc") {
                dir = "desc";
                switching = true;
            }
        }
    }
}
</script>

</body>
</html>
