        }
        .quiz-box {
            background-color: #34495e;
            padding: 20px;
            border-radius: 8px;
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
            width: 300px;
            text-align: center;
        }
        .question {
            font-size: 20px;
            margin-bottom: 20px;
        }
        .options {
            display: flex;
            flex-direction: column;
        }
        .option {
            background-color: #4a5f74;
            color: #ecf0f1;
            padding: 10px;
            border-radius: 4px;
            margin-bottom: 10px;
            cursor: pointer;
        }
        .option:hover {
            background-color: #34495e;
        }
        .result {
            font-size: 24px;
            margin-top: 20px;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="quiz-box" id="quizBox">
            <div class="question" id="question">What is the capital of France?</div>
            <div class="options">
                <div class="option" onclick="checkAnswer('Paris')">Paris</div>
                <div class="option" onclick="checkAnswer('London')">London</div>
                <div class="option" onclick="checkAnswer('Berlin')">Berlin</div>
                <div class="option" onclick="checkAnswer('Madrid')">Madrid</div>
            </div>
            <div class="result" id="result"></div>
        </div>
    </div>

    <script>
        let score = 0;
        const questions = [
            { question: "What is the capital of France?", answer: "Paris" },
            { question: "What is the largest planet in our solar system?", answer: "Jupiter" },
            { question: "Who wrote 'To Kill a Mockingbird'?", answer: "Harper Lee" }
        ];
        let currentQuestionIndex = 0;

        function checkAnswer(userAnswer) {
            const correctAnswer = questions[currentQuestionIndex].answer;
            if (userAnswer === correctAnswer) {
                score++;
                document.getElementById('result').innerText = 'Correct!';
            } else {
                document.getElementById('result').innerText = 'Wrong!';
            }
            currentQuestionIndex++;
            if (currentQuestionIndex < questions.length) {
                displayQuestion();
            } else {
                showScore();
            }
        }

        function displayQuestion() {
            const questionElement = document.getElementById('question');
            const optionsElement = document.querySelector('.options');
            questionElement.innerText = questions[currentQuestionIndex].question;
            optionsElement.innerHTML = '';
            ['Paris', 'London', 'Berlin', 'Madrid'].forEach(option => {
                const optionElement = document.createElement('div');
                optionElement.classList.add('option');
                optionElement.innerText = option;
                optionElement.onclick = () => checkAnswer(option);
                optionsElement.appendChild(optionElement);
            });
        }

        function showScore() {
            document.getElementById('question').innerText = `Your score: ${score}/${questions.length}`;
            document.querySelector('.options').innerHTML = '';
            document.getElementById('result').innerText = '';
        }

        displayQuestion();
    </script>
</body>
</html>
