// QuizScreen.tsx
import React, { useState } from 'react';
import { motion } from 'framer-motion';

const QuizScreen: React.FC = () => {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [score, setScore] = useState(0);
  const [answers, setAnswers] = useState<{ correct: boolean; text: string }[]>([]);
  const [isAnswered, setIsAnswered] = useState(false);

  const questions = [
    {
      question: 'What is the capital of France?',
      options: ['Paris', 'London', 'Berlin', 'Madrid'],
      correctAnswer: 'Paris',
    },
    {
      question: 'Which programming language is often used for web development?',
      options: ['Java', 'Python', 'JavaScript', 'C++'],
      correctAnswer: 'JavaScript',
    },
  ];

  const handleAnswer = (option: string) => {
    if (!isAnswered) {
      const isCorrect = option === questions[currentQuestion].correctAnswer;
      setScore(isCorrect ? score + 1 : score);
      setAnswers([...answers, { correct: isCorrect, text: option }]);
      setIsAnswered(true);
    }
  };

  const handleNextQuestion = () => {
    setCurrentQuestion(currentQuestion + 1);
    setIsAnswered(false);
  };

  const handleRestartQuiz = () => {
    setCurrentQuestion(0);
    setScore(0);
    setAnswers([]);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5 }}
      className="flex flex-col items-center justify-center h-screen bg-gray-100"
    >
      {currentQuestion < questions.length ? (
        <>
          <h2 className="text-2xl font-bold mb-4">{questions[currentQuestion].question}</h2>
          <div className="grid grid-cols-2 gap-4">
            {questions[currentQuestion].options.map((option, index) => (
              <button
                key={index}
                onClick={() => handleAnswer(option)}
                disabled={isAnswered}
                className={`px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 ${
                  isAnswered && answers[currentQuestion].text === option ? 'bg-green-500' : ''
                }`}
              >
                {option}
              </button>
            ))}
          </div>
          {isAnswered && (
            <button
              onClick={handleNextQuestion}
              className="mt-4 px-4 py-2 bg-green-500 text-white rounded hover:bg-green-600"
            >
              Next Question
            </button>
