        }
        .container {
            width: 50%;
            margin: 0 auto;
        }
        .cart-item {
            border-bottom: 1px solid #ccc;
            padding: 10px 0;
        }
        .total {
            text-align: right;
            font-weight: bold;
        }
        .form-group {
            margin-bottom: 15px;
        }
        .form-group label {
            display: block;
            margin-bottom: 5px;
        }
        .form-group input, .form-group select {
            width: 100%;
            padding: 8px;
            box-sizing: border-box;
        }
    </style>
</head>
<body>
    <div class="container">
        <h2>Review Your Cart</h2>
        <div class="cart-item">
            <span>Product 1 - $20</span>
        </div>
        <div class="cart-item">
            <span>Product 2 - $30</span>
        </div>
        <div class="total">Total: $50</div>

        <h2>Shipping Address</h2>
        <form id="shippingForm">
            <div class="form-group">
                <label for="name">Name:</label>
                <input type="text" id="name" name="name" required>
            </div>
            <div class="form-group">
                <label for="address">Address:</label>
                <input type="text" id="address" name="address" required>
            </div>
            <div class="form-group">
                <label for="city">City:</label>
                <input type="text" id="city" name="city" required>
            </div>
            <div class="form-group">
                <label for="state">State:</label>
                <input type="text" id="state" name="state" required>
            </div>
            <div class="form-group">
                <label for="zip">Zip Code:</label>
                <input type="text" id="zip" name="zip" required>
            </div>
        </form>

        <h2>Delivery Option</h2>
        <form id="deliveryForm">
            <div class="form-group">
                <label for="deliveryOption">Choose Delivery Option:</label>
                <select id="deliveryOption" name="deliveryOption" required>
                    <option value="standard">Standard (3-5 days) - $5</option>
                    <option value="express">Express (1-2 days) - $10</option>
                </select>
            </div>
        </form>

        <button id="submitBtn">Submit Order</button>
    </div>

    <script>
        document.getElementById('submitBtn').addEventListener('click', function() {
            const shippingForm = document.getElementById('shippingForm');
            const deliveryForm = document.getElementById('deliveryForm');

            if (shippingForm.checkValidity() && deliveryForm.checkValidity()) {
                alert('Order submitted successfully!');
                // Here you would typically send the data to a server
            } else {
                alert('Please fill out all required fields.');
            }
        });
    </script>
</body>
</html>
