      "content": "// ShippingForm component to capture shipping details
import React, { useState } from 'react';

const ShippingForm = ({ onShippingDetails }) => {
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [state, setState] = useState('');
  const [zip, setZip] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onShippingDetails({ address, city, state, zip });
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="address">Address:</label>
        <input type="text" id="address" value={address} onChange={(e) => setAddress(e.target.value)} required />
      </div>
      <div>
        <label htmlFor="city">City:</label>
        <input type="text" id="city" value={city} onChange={(e) => setCity(e.target.value)} required />
      </div>
      <div>
        <label htmlFor="state">State:</label>
        <input type="text" id="state" value={state} onChange={(e) => setState(e.target.value)} required />
      </div>
      <div>
        <label htmlFor="zip">Zip Code:</label>
        <input type="text" id="zip" value={zip} onChange={(e) => setZip(e.target.value)} required />
      </div>
      <button type="submit">Next</button>
    </form>
  );
};

export default ShippingForm;"
