    onDeliveryOption(e.target.value);
  };

  return (
    <div>
      <h2>Delivery Options</h2>
      <label>
        <input type="radio" name="delivery" value="standard" onChange={handleOptionChange} /> Standard (3-5 days)
      </label>
      <label>
        <input type="radio" name="delivery" value="express" onChange={handleOptionChange} /> Express (1-2 days)
      </label>
      <button onClick={() => onDeliveryOption('standard')}>Proceed to Payment</button>
    </div>
  );
};

export default DeliveryOptions;"
