<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Registration Form</title>
    <style>
        .error {
            color: red;
        }
    </style>
</head>
<body>
    <form id="registrationForm">
        <label for="username">Username:</label>
        <input type="text" id="username" name="username" required><br><br>

        <label for="password">Password:</label>
        <input type="password" id="password" name="password" required><br>
        <span id="passwordStrength" class="error"></span><br>

        <label for="confirmPassword">Confirm Password:</label>
        <input type="password" id="confirmPassword" name="confirmPassword" required><br>
        <span id="confirmPasswordMatch" class="error"></span><br>

        <button type="submit">Register</button>
    </form>

    <script>
        const passwordInput = document.getElementById('password');
        const confirmPasswordInput = document.getElementById('confirmPassword');
        const passwordStrengthSpan = document.getElementById('passwordStrength');
        const confirmPasswordMatchSpan = document.getElementById('confirmPasswordMatch');

        function checkPasswordStrength(password) {
            let strength = 0;
            if (password.length >= 8) strength++;
            if (/[a-z]/.test(password)) strength++;
            if (/[A-Z]/.test(password)) strength++;
            if (/\d/.test(password)) strength++;
            if (/[^a-zA-Z\d]/.test(password)) strength++;

            switch (strength) {
                case 1:
                    passwordStrengthSpan.textContent = 'Very Weak';
                    break;
                case 2:
                    passwordStrengthSpan.textContent = 'Weak';
                    break;
                case 3:
                    passwordStrengthSpan.textContent = 'Moderate';
                    break;
                case 4:
                    passwordStrengthSpan.textContent = 'Strong';
                    break;
                case 5:
                    passwordStrengthSpan.textContent = 'Very Strong';
                    break;
                default:
                    passwordStrengthSpan.textContent = '';
            }
        }

        function checkConfirmPasswordMatch() {
            if (passwordInput.value !== confirmPasswordInput.value) {
                confirmPasswordMatchSpan.textContent = 'Passwords do not match';
            } else {
                confirmPasswordMatchSpan.textContent = '';
            }
        }

        passwordInput.addEventListener('input', () => {
            checkPasswordStrength(passwordInput.value);
            checkConfirmPasswordMatch();
        });

        confirmPasswordInput.addEventListener('input', () => {
            checkConfirmPasswordMatch();
        });

        document.getElementById('registrationForm').addEventListener('submit', (event) => {
            event.preventDefault();
            if (passwordInput.value !== confirmPasswordInput.value) {
                confirmPasswordMatchSpan.textContent = 'Passwords do not match';
            } else {
                alert('Registration successful!');
                // Add code here to handle form submission
            }
        });
    </script>
</body>
</html>
