        <span id="confirmPasswordMatch" class="error"></span><br>

        <button type="submit">Register</button>
    </form>

    <script>
        document.getElementById('registrationForm').addEventListener('submit', function(event) {
            event.preventDefault();
            validateForm();
        });

        function validateForm() {
            const password = document.getElementById('password').value;
            const confirmPassword = document.getElementById('confirmPassword').value;
            const passwordStrength = document.getElementById('passwordStrength');
            const confirmPasswordMatch = document.getElementById('confirmPasswordMatch');

            // Password strength validation
            if (password.length < 8) {
                passwordStrength.textContent = 'Password must be at least 8 characters long.';
            } else if (!/[A-Z]/.test(password)) {
                passwordStrength.textContent = 'Password must contain at least one uppercase letter.';
            } else if (!/[a-z]/.test(password)) {
                passwordStrength.textContent = 'Password must contain at least one lowercase letter.';
            } else if (!/\d/.test(password)) {
                passwordStrength.textContent = 'Password must contain at least one number.';
            } else if (!/[^A-Za-z\d]/.test(password)) {
                passwordStrength.textContent = 'Password must contain at least one special character.';
            } else {
                passwordStrength.textContent = '';
            }

            // Confirm password match validation
            if (password !== confirmPassword) {
                confirmPasswordMatch.textContent = 'Passwords do not match.';
            } else {
                confirmPasswordMatch.textContent = '';
            }

            // If all validations pass, submit the form
            if (!passwordStrength.textContent && !confirmPasswordMatch.textContent) {
                this.submit();
            }
        }
